mapper.update:
UPDATE buyer_company
SET seal_verify_id = #{verifyId},
    entity_id = #{entityId}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE buyer_company
SET fadada_free_sign_business_id = #{businessId},
    fadada_free_sign_expire_time = #{expireTime,jdbcType=TIMESTAMP}
WHERE fadada_seal_id = #{sealId}
  AND is_deleted = 0

UPDATE buyer_company
SET seal_flow_status = 2,
    seal_failed_reason = #{reason}
WHERE seal_verify_id = #{verifyId}
  AND is_deleted = 0

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM buyer_company
    WHERE credit_code = #{creditCode}
      AND is_deleted = 0

        AND id != #{excludeId}

)
